//go:build e2e

package e2e

import (
	"regexp"
	"strings"
	"testing"
)

// AssertFileContains checks that a file contains the expected substring.
func AssertFileContains(t *testing.T, env *TestEnv, path, expected string) {
	t.Helper()

	content := env.ReadFile(path)
	if !strings.Contains(content, expected) {
		t.Errorf("File %s does not contain expected string.\nExpected substring: %q\nActual content:\n%s",
			path, expected, content)
	}
}

// AssertFileMatches checks that a file content matches a regex pattern.
func AssertFileMatches(t *testing.T, env *TestEnv, path, pattern string) {
	t.Helper()

	content := env.ReadFile(path)
	matched, err := regexp.MatchString(pattern, content)
	if err != nil {
		t.Fatalf("Invalid regex pattern %q: %v", pattern, err)
	}
	if !matched {
		t.Errorf("File %s does not match pattern.\nPattern: %q\nActual content:\n%s",
			path, pattern, content)
	}
}

// AssertHelloWorldProgram verifies a Go file is a valid hello world program.
// Uses flexible matching to handle agent variations.
func AssertHelloWorldProgram(t *testing.T, env *TestEnv, path string) {
	t.Helper()

	content := env.ReadFile(path)

	// Check for package main
	if !strings.Contains(content, "package main") {
		t.Errorf("File %s missing 'package main'", path)
	}

	// Check for main function (flexible whitespace)
	mainFuncPattern := regexp.MustCompile(`func\s+main\s*\(\s*\)`)
	if !mainFuncPattern.MatchString(content) {
		t.Errorf("File %s missing main function", path)
	}

	// Check for Hello, World! (case insensitive)
	helloPattern := regexp.MustCompile(`(?i)hello.+world`)
	if !helloPattern.MatchString(content) {
		t.Errorf("File %s missing 'Hello, World!' output", path)
	}
}

// AssertCalculatorFunctions verifies calc.go has the expected functions.
func AssertCalculatorFunctions(t *testing.T, env *TestEnv, path string, functions ...string) {
	t.Helper()

	content := env.ReadFile(path)

	for _, fn := range functions {
		// Check for function definition (flexible whitespace)
		pattern := regexp.MustCompile(`func\s+` + regexp.QuoteMeta(fn) + `\s*\(`)
		if !pattern.MatchString(content) {
			t.Errorf("File %s missing function %s", path, fn)
		}
	}
}

// AssertRewindPointExists checks that at least one rewind point exists.
func AssertRewindPointExists(t *testing.T, env *TestEnv) {
	t.Helper()

	points := env.GetRewindPoints()
	if len(points) == 0 {
		t.Error("Expected at least one rewind point, but none exist")
	}
}

// AssertRewindPointCount checks that the expected number of rewind points exist.
func AssertRewindPointCount(t *testing.T, env *TestEnv, expected int) {
	t.Helper()

	points := env.GetRewindPoints()
	if len(points) != expected {
		t.Errorf("Expected %d rewind points, got %d", expected, len(points))
		for i, p := range points {
			t.Logf("  Point %d: ID=%s, Message=%s", i, p.ID, p.Message)
		}
	}
}

// AssertRewindPointCountAtLeast checks that at least the expected number of rewind points exist.
func AssertRewindPointCountAtLeast(t *testing.T, env *TestEnv, minimum int) {
	t.Helper()

	points := env.GetRewindPoints()
	if len(points) < minimum {
		t.Errorf("Expected at least %d rewind points, got %d", minimum, len(points))
		for i, p := range points {
			t.Logf("  Point %d: ID=%s, Message=%s", i, p.ID, p.Message)
		}
	}
}

// AssertCheckpointExists checks that a checkpoint trailer exists in commit history.
func AssertCheckpointExists(t *testing.T, env *TestEnv) {
	t.Helper()

	checkpointID, err := env.GetLatestCheckpointIDFromHistory()
	if err != nil || checkpointID == "" {
		t.Errorf("Expected checkpoint trailer in commit history, but none found: %v", err)
	}
}

// AssertBranchExists checks that a branch exists.
func AssertBranchExists(t *testing.T, env *TestEnv, branchName string) {
	t.Helper()

	if !env.BranchExists(branchName) {
		t.Errorf("Expected branch %s to exist, but it doesn't", branchName)
	}
}

// AssertAgentSuccess checks that an agent result indicates success.
func AssertAgentSuccess(t *testing.T, result *AgentResult, err error) {
	t.Helper()

	if err != nil {
		stderr := ""
		if result != nil {
			stderr = result.Stderr
		}
		t.Errorf("Agent failed with error: %v\nStderr: %s", err, stderr)
	}
	if result != nil && result.ExitCode != 0 {
		t.Errorf("Agent exited with code %d\nStdout: %s\nStderr: %s",
			result.ExitCode, result.Stdout, result.Stderr)
	}
}

// AssertExpectedFilesExist checks that all expected files from a prompt template exist.
func AssertExpectedFilesExist(t *testing.T, env *TestEnv, prompt PromptTemplate) {
	t.Helper()

	for _, file := range prompt.ExpectedFiles {
		if !env.FileExists(file) {
			t.Errorf("Expected file %s to exist after prompt %s, but it doesn't", file, prompt.Name)
		}
	}
}

//go:build e2e

package e2e

// PromptTemplate defines a deterministic prompt with expected outcomes.
type PromptTemplate struct {
	Name          string   // Unique name for the prompt
	Prompt        string   // The actual prompt text
	ExpectedFiles []string // Files expected to be created/modified
}

// Deterministic prompts designed for predictable outcomes with minimal token usage.

// PromptCreateHelloGo creates a simple Go hello world program.
var PromptCreateHelloGo = PromptTemplate{
	Name: "CreateHelloGo",
	Prompt: `Create a file called hello.go with a simple Go program that prints "Hello, World!".
Requirements:
- Use package main
- Use a main function
- Use fmt.Println to print exactly "Hello, World!"
- Do not add comments, tests, or extra functionality
- Do not create any other files`,
	ExpectedFiles: []string{"hello.go"},
}

// PromptModifyHelloGo modifies the hello.go file to print a different message.
var PromptModifyHelloGo = PromptTemplate{
	Name: "ModifyHelloGo",
	Prompt: `Modify hello.go to print "Hello, E2E Test!" instead of "Hello, World!".
Do not add any other functionality or files.`,
	ExpectedFiles: []string{"hello.go"},
}

// PromptCreateCalculator creates a simple calculator with add/subtract functions.
var PromptCreateCalculator = PromptTemplate{
	Name: "CreateCalculator",
	Prompt: `Create a file called calc.go with two exported functions:
- Add(a, b int) int - returns a + b
- Subtract(a, b int) int - returns a - b
Requirements:
- Use package main
- No comments or documentation
- No main function
- No tests
- No other files`,
	ExpectedFiles: []string{"calc.go"},
}

// PromptCreateConfig creates a simple JSON config file.
var PromptCreateConfig = PromptTemplate{
	Name: "CreateConfig",
	Prompt: `Create a file called config.json with this exact content:
{
  "name": "e2e-test",
  "version": "1.0.0",
  "enabled": true
}
Do not create any other files.`,
	ExpectedFiles: []string{"config.json"},
}

// PromptAddMultiplyFunction adds a multiply function to calc.go.
var PromptAddMultiplyFunction = PromptTemplate{
	Name: "AddMultiplyFunction",
	Prompt: `Add a Multiply function to calc.go that multiplies two integers.
- Signature: Multiply(a, b int) int
- No comments
- No other changes`,
	ExpectedFiles: []string{"calc.go"},
}

// PromptCreateDocs creates a simple DOCS.md documentation file.
// Note: Uses DOCS.md instead of README.md to avoid conflicts with
// the README.md created by NewFeatureBranchEnv during test setup.
var PromptCreateDocs = PromptTemplate{
	Name: "CreateDocs",
	Prompt: `Create a file called DOCS.md with exactly this content:
# Documentation

This is the documentation file.

## Usage

Run the program with: go run .
`,
	ExpectedFiles: []string{"DOCS.md"},
}

// PromptCommitChanges instructs the agent to commit changes.
// This is used to test agent commits during a turn.
var PromptCommitChanges = PromptTemplate{
	Name: "CommitChanges",
	Prompt: `Stage and commit all changes with the message "Add feature via agent".
Use git add and git commit commands.`,
	ExpectedFiles: []string{},
}

//go:build e2e

package e2e

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/format/config"
	"github.com/go-git/go-git/v5/plumbing/object"
)

// TestEnv manages an isolated test environment for E2E tests with real agent calls.
type TestEnv struct {
	T       *testing.T
	RepoDir string
	Agent   AgentRunner
}

// NewTestEnv creates a new isolated E2E test environment.
func NewTestEnv(t *testing.T) *TestEnv {
	t.Helper()

	// Resolve symlinks on macOS where /var -> /private/var
	repoDir := t.TempDir()
	if resolved, err := filepath.EvalSymlinks(repoDir); err == nil {
		repoDir = resolved
	}

	// Create agent runner
	agent := NewAgentRunner(defaultAgent, AgentRunnerConfig{})

	return &TestEnv{
		T:       t,
		RepoDir: repoDir,
		Agent:   agent,
	}
}

// NewFeatureBranchEnv creates an E2E test environment ready for testing.
// It initializes the repo, creates an initial commit on main,
// checks out a feature branch, and sets up agent hooks.
func NewFeatureBranchEnv(t *testing.T, strategyName string) *TestEnv {
	t.Helper()

	env := NewTestEnv(t)
	env.InitRepo()
	env.WriteFile("README.md", "# Test Repository\n\nThis is a test repository for E2E testing.\n")
	env.GitAdd("README.md")
	env.GitCommit("Initial commit")
	env.GitCheckoutNewBranch("feature/e2e-test")

	// Use `entire enable` to set up everything (hooks, settings, etc.)
	// This sets up .entire/settings.json and .claude/settings.json with hooks
	env.RunEntireEnable(strategyName)

	// Commit all files created by `entire enable` so they survive git stash -u operations.
	// Without this, stash operations would stash away the hooks config and entire settings,
	// causing hooks to not fire for subsequent prompts and stash pop conflicts.
	// Using "git add ." is safe in test repos since we control all content.
	env.GitAddAll()
	env.GitCommit("Add entire and agent config")

	return env
}

// RunEntireEnable runs `entire enable` to set up the project with hooks.
// Uses the configured defaultAgent (from E2E_AGENT env var or "claude-code").
func (env *TestEnv) RunEntireEnable(strategyName string) {
	env.T.Helper()

	args := []string{
		"enable",
		"--agent", defaultAgent,
		"--strategy", strategyName,
		"--telemetry=false",
		"--force", // Force reinstall hooks in case they exist
	}

	//nolint:gosec,noctx // test code, args are static
	cmd := exec.Command(getTestBinary(), args...)
	cmd.Dir = env.RepoDir

	output, err := cmd.CombinedOutput()
	if err != nil {
		env.T.Fatalf("entire enable failed: %v\nOutput: %s", err, output)
	}
	env.T.Logf("entire enable output: %s", output)
}

// InitRepo initializes a git repository in the test environment.
func (env *TestEnv) InitRepo() {
	env.T.Helper()

	repo, err := git.PlainInit(env.RepoDir, false)
	if err != nil {
		env.T.Fatalf("failed to init git repo: %v", err)
	}

	// Configure git user for commits
	cfg, err := repo.Config()
	if err != nil {
		env.T.Fatalf("failed to get repo config: %v", err)
	}
	cfg.User.Name = "E2E Test User"
	cfg.User.Email = "e2e-test@example.com"

	// Disable GPG signing for test commits
	if cfg.Raw == nil {
		cfg.Raw = config.New()
	}
	cfg.Raw.Section("commit").SetOption("gpgsign", "false")

	if err := repo.SetConfig(cfg); err != nil {
		env.T.Fatalf("failed to set repo config: %v", err)
	}
}

// WriteFile creates a file with the given content in the test repo.
func (env *TestEnv) WriteFile(path, content string) {
	env.T.Helper()

	fullPath := filepath.Join(env.RepoDir, path)

	// Create parent directories
	dir := filepath.Dir(fullPath)
	//nolint:gosec // test code, permissions are intentionally standard
	if err := os.MkdirAll(dir, 0o755); err != nil {
		env.T.Fatalf("failed to create directory %s: %v", dir, err)
	}

	//nolint:gosec // test code, permissions are intentionally standard
	if err := os.WriteFile(fullPath, []byte(content), 0o644); err != nil {
		env.T.Fatalf("failed to write file %s: %v", path, err)
	}
}

// ReadFile reads a file from the test repo.
func (env *TestEnv) ReadFile(path string) string {
	env.T.Helper()

	fullPath := filepath.Join(env.RepoDir, path)
	//nolint:gosec // test code, path is from test setup
	data, err := os.ReadFile(fullPath)
	if err != nil {
		env.T.Fatalf("failed to read file %s: %v", path, err)
	}
	return string(data)
}

// TryReadFile reads a file from the test repo, returning empty string if not found.
func (env *TestEnv) TryReadFile(path string) string {
	env.T.Helper()

	fullPath := filepath.Join(env.RepoDir, path)
	//nolint:gosec // test code, path is from test setup
	data, err := os.ReadFile(fullPath)
	if err != nil {
		return ""
	}
	return string(data)
}

// FileExists checks if a file exists in the test repo.
func (env *TestEnv) FileExists(path string) bool {
	env.T.Helper()

	fullPath := filepath.Join(env.RepoDir, path)
	_, err := os.Stat(fullPath)
	return err == nil
}

// GitAdd stages files for commit.
func (env *TestEnv) GitAdd(paths ...string) {
	env.T.Helper()

	repo, err := git.PlainOpen(env.RepoDir)
	if err != nil {
		env.T.Fatalf("failed to open git repo: %v", err)
	}

	worktree, err := repo.Worktree()
	if err != nil {
		env.T.Fatalf("failed to get worktree: %v", err)
	}

	for _, path := range paths {
		if _, err := worktree.Add(path); err != nil {
			env.T.Fatalf("failed to add file %s: %v", path, err)
		}
	}
}

// GitAddAll stages all files (git add .).
func (env *TestEnv) GitAddAll() {
	env.T.Helper()

	//nolint:gosec // test code, "." is safe
	cmd := exec.Command("git", "add", ".")
	cmd.Dir = env.RepoDir
	if output, err := cmd.CombinedOutput(); err != nil {
		env.T.Fatalf("git add . failed: %v\nOutput: %s", err, output)
	}
}

// GitCommit creates a commit with all staged files.
func (env *TestEnv) GitCommit(message string) {
	env.T.Helper()

	repo, err := git.PlainOpen(env.RepoDir)
	if err != nil {
		env.T.Fatalf("failed to open git repo: %v", err)
	}

	worktree, err := repo.Worktree()
	if err != nil {
		env.T.Fatalf("failed to get worktree: %v", err)
	}

	_, err = worktree.Commit(message, &git.CommitOptions{
		Author: &object.Signature{
			Name:  "E2E Test User",
			Email: "e2e-test@example.com",
			When:  time.Now(),
		},
	})
	if err != nil {
		env.T.Fatalf("failed to commit: %v", err)
	}
}

// GitCommitWithShadowHooks stages and commits files, running the prepare-commit-msg
// and post-commit hooks like a real workflow.
func (env *TestEnv) GitCommitWithShadowHooks(message string, files ...string) {
	env.T.Helper()

	// Stage files using go-git
	for _, file := range files {
		env.GitAdd(file)
	}

	// Create a temp file for the commit message
	msgFile := filepath.Join(env.RepoDir, ".git", "COMMIT_EDITMSG")
	//nolint:gosec // test code, permissions are intentionally standard
	if err := os.WriteFile(msgFile, []byte(message), 0o644); err != nil {
		env.T.Fatalf("failed to write commit message file: %v", err)
	}

	// Run prepare-commit-msg hook
	//nolint:gosec,noctx // test code, args are from trusted test setup, no context needed
	prepCmd := exec.Command(getTestBinary(), "hooks", "git", "prepare-commit-msg", msgFile, "message")
	prepCmd.Dir = env.RepoDir
	prepCmd.Env = append(os.Environ(),
		"ENTIRE_TEST_TTY=1",
		"ENTIRE_TEST_CLAUDE_PROJECT_DIR="+filepath.Join(env.RepoDir, ".claude"),
		"ENTIRE_TEST_GEMINI_PROJECT_DIR="+filepath.Join(env.RepoDir, ".gemini"),
	)
	if output, err := prepCmd.CombinedOutput(); err != nil {
		env.T.Logf("prepare-commit-msg output: %s", output)
	}

	// Read the modified message
	//nolint:gosec // test code, path is from test setup
	modifiedMsg, err := os.ReadFile(msgFile)
	if err != nil {
		env.T.Fatalf("failed to read modified commit message: %v", err)
	}

	// Create the commit using go-git with the modified message
	repo, err := git.PlainOpen(env.RepoDir)
	if err != nil {
		env.T.Fatalf("failed to open git repo: %v", err)
	}

	worktree, err := repo.Worktree()
	if err != nil {
		env.T.Fatalf("failed to get worktree: %v", err)
	}

	_, err = worktree.Commit(string(modifiedMsg), &git.CommitOptions{
		Author: &object.Signature{
			Name:  "E2E Test User",
			Email: "e2e-test@example.com",
			When:  time.Now(),
		},
	})
	if err != nil {
		env.T.Fatalf("failed to commit: %v", err)
	}

	// Run post-commit hook
	//nolint:gosec,noctx // test code, args are from trusted test setup, no context needed
	postCmd := exec.Command(getTestBinary(), "hooks", "git", "post-commit")
	postCmd.Dir = env.RepoDir
	postCmd.Env = append(os.Environ(),
		"ENTIRE_TEST_CLAUDE_PROJECT_DIR="+filepath.Join(env.RepoDir, ".claude"),
		"ENTIRE_TEST_GEMINI_PROJECT_DIR="+filepath.Join(env.RepoDir, ".gemini"),
	)
	if output, err := postCmd.CombinedOutput(); err != nil {
		env.T.Logf("post-commit output: %s", output)
	}
}

// GitCheckoutNewBranch creates and checks out a new branch.
func (env *TestEnv) GitCheckoutNewBranch(branchName string) {
	env.T.Helper()

	//nolint:noctx // test code, no context needed for git checkout
	cmd := exec.Command("git", "checkout", "-b", branchName)
	cmd.Dir = env.RepoDir
	if output, err := cmd.CombinedOutput(); err != nil {
		env.T.Fatalf("failed to checkout new branch %s: %v\nOutput: %s", branchName, err, output)
	}
}

// GetHeadHash returns the current HEAD commit hash.
func (env *TestEnv) GetHeadHash() string {
	env.T.Helper()

	repo, err := git.PlainOpen(env.RepoDir)
	if err != nil {
		env.T.Fatalf("failed to open git repo: %v", err)
	}

	head, err := repo.Head()
	if err != nil {
		env.T.Fatalf("failed to get HEAD: %v", err)
	}

	return head.Hash().String()
}

// RewindPoint mirrors the rewind --list JSON output.
type RewindPoint struct {
	ID               string    `json:"id"`
	Message          string    `json:"message"`
	MetadataDir      string    `json:"metadata_dir"`
	Date             time.Time `json:"date"`
	IsTaskCheckpoint bool      `json:"is_task_checkpoint"`
	ToolUseID        string    `json:"tool_use_id"`
	IsLogsOnly       bool      `json:"is_logs_only"`
	CondensationID   string    `json:"condensation_id"`
}

// GetRewindPoints returns available rewind points using the CLI.
func (env *TestEnv) GetRewindPoints() []RewindPoint {
	env.T.Helper()

	//nolint:gosec,noctx // test code, args are static, no context needed
	cmd := exec.Command(getTestBinary(), "rewind", "--list")
	cmd.Dir = env.RepoDir

	output, err := cmd.CombinedOutput()
	if err != nil {
		env.T.Fatalf("rewind --list failed: %v\nOutput: %s", err, output)
	}

	// Parse JSON output
	var jsonPoints []struct {
		ID               string `json:"id"`
		Message          string `json:"message"`
		MetadataDir      string `json:"metadata_dir"`
		Date             string `json:"date"`
		IsTaskCheckpoint bool   `json:"is_task_checkpoint"`
		ToolUseID        string `json:"tool_use_id"`
		IsLogsOnly       bool   `json:"is_logs_only"`
		CondensationID   string `json:"condensation_id"`
	}

	if err := json.Unmarshal(output, &jsonPoints); err != nil {
		env.T.Fatalf("failed to parse rewind points: %v\nOutput: %s", err, output)
	}

	points := make([]RewindPoint, len(jsonPoints))
	for i, jp := range jsonPoints {
		//nolint:errcheck // date parsing failure is acceptable, defaults to zero time
		date, _ := time.Parse(time.RFC3339, jp.Date)
		points[i] = RewindPoint{
			ID:               jp.ID,
			Message:          jp.Message,
			MetadataDir:      jp.MetadataDir,
			Date:             date,
			IsTaskCheckpoint: jp.IsTaskCheckpoint,
			ToolUseID:        jp.ToolUseID,
			IsLogsOnly:       jp.IsLogsOnly,
			CondensationID:   jp.CondensationID,
		}
	}

	return points
}

