// extractSignificantLines returns a set of significant (non-trivial) lines from content.
// Lines are trimmed and must be at least 10 characters and not boilerplate.
func extractSignificantLines(content string) map[string]bool {
	lines := make(map[string]bool)
	for _, line := range splitLines([]byte(content)) {
		trimmed := trimLine(line)
		if len(trimmed) >= 10 && !isTrivialLine(trimmed) {
			lines[trimmed] = true
		}
	}
	return lines
}

// trimLine removes leading and trailing whitespace from a line.
func trimLine(line string) string {
	start := 0
	end := len(line)
	for start < end && (line[start] == ' ' || line[start] == '\t') {
		start++
	}
	for end > start && (line[end-1] == ' ' || line[end-1] == '\t') {
		end--
	}
	return line[start:end]
}

// isTrivialLine returns true for lines that are likely structural boilerplate
// rather than meaningful content. Uses a language-agnostic heuristic based on
// alphanumeric character ratio - lines that are mostly punctuation/symbols
// (like `});`, `])`, `{`) are considered trivial.
func isTrivialLine(line string) bool {
	if len(line) == 0 {
		return true
	}

	// Count alphanumeric characters
	alphanumeric := 0
	for i := 0; i < len(line); i++ {
		c := line[i]
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') {
			alphanumeric++
		}
	}

	// Lines with < 40% alphanumeric content are likely structural
	// Examples that would be filtered: `});`, `])`, `{`, `} else {`
	// Examples that would pass: `user.Save()`, `return err`, `x := 5`
	return float64(alphanumeric)/float64(len(line)) < 0.4
}

