	createShadowBranchWithContent(t, repo, "ghi9012", "e3b0c4", map[string][]byte{
		"newfile.txt": []byte("agent original content"),
	})

	// Get shadow tree
	shadowBranch := checkpoint.ShadowBranchNameForCommit("ghi9012", "e3b0c4")
	shadowRef, err := repo.Reference(plumbing.NewBranchReferenceName(shadowBranch), true)
	require.NoError(t, err)
	shadowCommit, err := repo.CommitObject(shadowRef.Hash())
	require.NoError(t, err)
	shadowTree, err := shadowCommit.Tree()
	require.NoError(t, err)

	// New file with different content should NOT count as overlap
	result := stagedFilesOverlapWithContent(repo, shadowTree, []string{"newfile.txt"}, []string{"newfile.txt"})
	assert.False(t, result, "New file with mismatched content should not count as overlap")
}

// TestStagedFilesOverlapWithContent_NoOverlap tests that non-overlapping files
// return false.
func TestStagedFilesOverlapWithContent_NoOverlap(t *testing.T) {
	t.Parallel()
	dir := setupGitRepo(t)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	// Stage a file NOT in filesTouched
	otherFile := filepath.Join(dir, "other.txt")
	require.NoError(t, os.WriteFile(otherFile, []byte("other content"), 0o644))
	wt, err := repo.Worktree()
	require.NoError(t, err)
	_, err = wt.Add("other.txt")
	require.NoError(t, err)

	// Create shadow branch
	createShadowBranchWithContent(t, repo, "jkl3456", "e3b0c4", map[string][]byte{
		"session.txt": []byte("session content"),
	})

	// Get shadow tree
	shadowBranch := checkpoint.ShadowBranchNameForCommit("jkl3456", "e3b0c4")
	shadowRef, err := repo.Reference(plumbing.NewBranchReferenceName(shadowBranch), true)
	require.NoError(t, err)
	shadowCommit, err := repo.CommitObject(shadowRef.Hash())
	require.NoError(t, err)
	shadowTree, err := shadowCommit.Tree()
	require.NoError(t, err)

	// Staged file "other.txt" is not in filesTouched "session.txt"
	result := stagedFilesOverlapWithContent(repo, shadowTree, []string{"other.txt"}, []string{"session.txt"})
	assert.False(t, result, "Non-overlapping files should return false")
}

// createShadowBranchWithContent creates a shadow branch with the given file contents.
// This helper directly uses go-git APIs to avoid paths.RepoRoot() dependency.
//
//nolint:unparam // worktreeID is kept as a parameter for flexibility even if tests currently use same value
func createShadowBranchWithContent(t *testing.T, repo *git.Repository, baseCommit, worktreeID string, fileContents map[string][]byte) {
	t.Helper()

	shadowBranchName := checkpoint.ShadowBranchNameForCommit(baseCommit, worktreeID)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)

	// Get HEAD for base tree
	head, err := repo.Head()
	require.NoError(t, err)

	headCommit, err := repo.CommitObject(head.Hash())
	require.NoError(t, err)

	baseTree, err := headCommit.Tree()
	require.NoError(t, err)

	// Flatten existing tree into map
	entries := make(map[string]object.TreeEntry)
	err = checkpoint.FlattenTree(repo, baseTree, "", entries)
	require.NoError(t, err)

	// Add/update files with provided content
	for filePath, content := range fileContents {
		// Create blob with content
		blob := repo.Storer.NewEncodedObject()
		blob.SetType(plumbing.BlobObject)
		blob.SetSize(int64(len(content)))
		writer, err := blob.Writer()
		require.NoError(t, err)
		_, err = writer.Write(content)
		require.NoError(t, err)
		err = writer.Close()
		require.NoError(t, err)

		blobHash, err := repo.Storer.SetEncodedObject(blob)
		require.NoError(t, err)

		entries[filePath] = object.TreeEntry{
			Name: filePath,
			Mode: filemode.Regular,
			Hash: blobHash,
		}
	}

	// Build tree from entries
	treeHash, err := checkpoint.BuildTreeFromEntries(repo, entries)
	require.NoError(t, err)

	// Create commit
	commit := &object.Commit{
		TreeHash: treeHash,
		Message:  "Test checkpoint",
		Author: object.Signature{
			Name:  "Test",
			Email: "test@test.com",
			When:  time.Now(),
		},
		Committer: object.Signature{
			Name:  "Test",
			Email: "test@test.com",
			When:  time.Now(),
		},
	}

	commitObj := repo.Storer.NewEncodedObject()
	err = commit.Encode(commitObj)
	require.NoError(t, err)

	commitHash, err := repo.Storer.SetEncodedObject(commitObj)
	require.NoError(t, err)

	// Create branch reference
	newRef := plumbing.NewHashReference(refName, commitHash)
	err = repo.Storer.SetReference(newRef)
	require.NoError(t, err)
}

// TestIsTrivialLine tests the language-agnostic trivial line detection.
// The heuristic uses alphanumeric character ratio (< 40% = trivial).
func TestIsTrivialLine(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name     string
		line     string
		wantTriv bool
	}{
		// Structural lines (should be trivial - low alphanumeric ratio)
		{"empty", "", true},
		{"single brace open", "{", true},
		{"single brace close", "}", true},
		{"single paren", ")", true},
		{"js object end", "});", true},
		{"array end", "]);", true},
		{"json close", "},", true},

		// Comments - various languages (mostly punctuation = trivial)
		{"c comment start", "/*", true},
		{"c comment end", "*/", true},
		{"short comment", "// x", true},
		{"python short comment", "# x", true},

		// Borderline cases - these have ~50% alphanumeric, so NOT trivial
		{"go else brace", "} else {", false}, // 50% alpha (4/8)
		{"go if err open", "if err != nil {", false},

		// Meaningful content (should NOT be trivial - high alphanumeric ratio)
		{"function call", "user.Save()", false},
		{"return statement", "return err", false},
		{"python def", "def hello():", false},
		{"js console", "console.log(msg)", false},
		{"import statement", "import React", false},
		{"python import", "from typing import List", false},
		{"sql query", "SELECT * FROM users", false},
		{"go func decl", "func main() {", false},
		{"variable decl", "const foo = bar", false},
		{"method call chain", "obj.method().chain()", false},

		// Edge cases
		{"spaces only", "     ", true},
		{"tabs only", "\t\t\t", true},
		{"mixed punct", "({[]})", true},
		{"url-like", "https://example.com", false},
		{"file path", "/usr/local/bin", false}, // 79% alpha (11/14) - NOT trivial
		{"windows path", "C:\\Users\\test", false},

		// Other languages
		{"ruby method", "def calculate(x)", false},
		{"rust let", "let mut x = 5;", false},
		{"java class", "public class Foo {", false},
		{"csharp namespace", "namespace MyApp {", false},
		{"swift func", "func doThing() -> Int {", false},
		{"kotlin fun", "fun calculate(): Int {", false},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			got := isTrivialLine(tt.line)
			if got != tt.wantTriv {
				// Calculate ratio for debugging
				alpha := 0
				for i := 0; i < len(tt.line); i++ {
					c := tt.line[i]
					if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') {
						alpha++
					}
				}
				ratio := 0.0
				if len(tt.line) > 0 {
					ratio = float64(alpha) / float64(len(tt.line))
				}
				t.Errorf("isTrivialLine(%q) = %v, want %v (ratio=%.2f, alpha=%d, len=%d)",
					tt.line, got, tt.wantTriv, ratio, alpha, len(tt.line))
			}
		})
	}
}

// TestExtractSignificantLines tests the full line extraction pipeline.
// Lines are filtered by: (1) minimum length of 10 chars, (2) alphanumeric ratio >= 40%.
func TestExtractSignificantLines(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name     string
		content  string
		wantKeys []string // lines that should be in the result
		wantNot  []string // lines that should NOT be in the result
	}{
		{
			name: "go function",
			content: `package main

func hello() {
	fmt.Println("hello world")
	return
}`,
			wantKeys: []string{
				"package main",                   // 11 chars, high alpha ratio
				"func hello() {",                 // 14 chars, high alpha ratio
				`fmt.Println("hello world")`,     // significant content
			},
			wantNot: []string{
				"}",      // single char, filtered by length
				"return", // 6 chars, filtered by length (<10)
			},
		},
		{
			name: "python function",
			content: `def calculate(x, y):
    result = x + y
    print(f"Result: {result}")
    return result`,
			wantKeys: []string{
				"def calculate(x, y):",        // high alpha ratio
				"result = x + y",              // significant
				`print(f"Result: {result}")`,  // significant
				"return result",               // 13 chars, significant
			},
			wantNot: []string{
				// All lines in this example are significant
			},
		},
		{
			name: "javascript with structural",
			content: `const handler = async (req) => {
  const data = await fetch(url);
  return data.json();
};`,
			wantKeys: []string{
				"const handler = async (req) => {",
				"const data = await fetch(url);",
				"return data.json();",
			},
			wantNot: []string{
				"};", // low alpha ratio (0%)
			},
		},
		{
			name: "short lines filtered",
			content: `a = 1
b = 2
longVariableName = 42`,
			wantKeys: []string{
				"longVariableName = 42",
			},
			wantNot: []string{
				"a = 1", // 5 chars, filtered by length (<10)
				"b = 2", // 5 chars, filtered by length (<10)
			},
		},
		{
			name: "structural lines filtered",
			content: `{
  });
  ]);
  },
}`,
			wantKeys: []string{
				// All lines are either too short or low alpha ratio
			},
			wantNot: []string{
				"{",
				"});",
				"]);",
				"},",
				"}",
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			result := extractSignificantLines(tt.content)

			for _, want := range tt.wantKeys {
				if !result[want] {
					t.Errorf("extractSignificantLines() missing expected line: %q", want)
				}
			}

			for _, notWant := range tt.wantNot {
				if result[notWant] {
					t.Errorf("extractSignificantLines() should not contain: %q", notWant)
				}
			}
		})
	}
}

